const C={purple:0x8871ce,indigo:0x6050ad,mint:0x70af91,green:0x428466,amber:0xe6b05e,peach:0xd89375,cream:0xf6eddb,ink:0x393246,wood:0xbb895c,blue:0x7ba5c7,red:0xce644f};
const materials=new Map(),geometries=new Map();
