function cylinder(p,rt,rb,h,x,y,z,c=C.wood){return mesh(p,geo(`c${rt},${rb},${h}`,()=>new T.CylinderGeometry(rt,rb,h,40,1)),typeof c==='object'?c:mat(c),x,y,z);}
