function text(p,str,x,y,z=50,size=21,color='#393246',background=null,maxWidth=450,format={}){str=String(str);const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d'),ratio=2;font();function font(){ctx.font=`${format.italic?'italic ':''}${format.weight||600} ${size*ratio}px ${format.family||'system-ui, "Noto Sans Devanagari", sans-serif'}`;}
 let width=Math.min(maxWidth,Math.max(size,ctx.measureText(str).width/ratio+18));canvas.width=Math.ceil(width*ratio);canvas.height=Math.ceil(size*2*ratio);font();ctx.textAlign='center';ctx.textBaseline='middle';if(background){ctx.fillStyle=background;ctx.beginPath();ctx.roundRect(0,0,canvas.width,canvas.height,12);ctx.fill();}ctx.fillStyle=color;ctx.fillText(str,canvas.width/2,canvas.height/2,canvas.width-12);if(format.underline)ctx.fillRect(9,canvas.height/2+size*.68,canvas.width-18,2.5);const texture=new T.CanvasTexture(canvas);texture.colorSpace=T.SRGBColorSpace;texture.minFilter=T.LinearFilter;const material=new T.SpriteMaterial({map:texture,depthTest:false,transparent:true});const sprite=new T.Sprite(material);sprite.position.set(x,y,z);sprite.scale.set(width,size*2,1);sprite.renderOrder=10;p.add(sprite);sprite.userData.disposableTexture=texture;return sprite;}
