 if(parts.includes('Flowers')){for(let i=0;i<5;i++){const a=i*Math.PI*2/5;ball(g,13,Math.sin(a)*17,211+Math.cos(a)*17,2,C.amber,[.75,1,.35]);}ball(g,9,0,211,8,0x83602e);}
