function bowl(p,x=0,y=0,z=0,scale=1,color=C.cream){const g=group(p,x,y,z);g.scale.setScalar(scale);const o=mesh(g,new T.SphereGeometry(43,32,16,0,Math.PI*2,Math.PI/2,Math.PI/2),mat(color,{side:T.DoubleSide}));o.scale.y=.5;const rim=mesh(g,new T.TorusGeometry(43,2.5,8,40),mat(color));rim.rotation.x=Math.PI/2;return g;}
