  this.world.add(new T.HemisphereLight(0xfff5dd,0x777088,1.4));const light=new T.DirectionalLight(0xfff2d5,3);light.position.set(-230,380,400);light.castShadow=true;light.shadow.mapSize.set(1024,1024);light.shadow.camera.left=-450;light.shadow.camera.right=450;light.shadow.camera.top=350;light.shadow.camera.bottom=-350;light.shadow.normalBias=1;light.shadow.bias=-.0002;light.shadow.radius=4;this.world.add(light);const rim=new T.DirectionalLight(0xcbdcfc,1.6);rim.position.set(350,100,-150);this.world.add(rim);
