  host.addEventListener('click',e=>{if(this.paused||document.querySelector('.quiz-scene'))return;const r=this.renderer.domElement.getBoundingClientRect(),ray=new T.Raycaster();ray.setFromCamera(new T.Vector2((e.clientX-r.left)/r.width*2-1,1-(e.clientY-r.top)/r.height*2),this.camera);for(const hit of ray.intersectObject(this.content,true)){let o=hit.object;while(o&&!o.userData.activate)o=o.parent;if(o?.userData.activate){o.userData.activate(hit);this.pulse();break;}}});
